<script setup>import{onMounted,ref}from'vue';import{api}from'../api.js';import PublicPageShell from'../components/PublicPageShell.vue';const data=ref(null);const status=e=>{const n=Date.now(),a=new Date(e.starts_at).getTime(),b=new Date(e.ends_at).getTime();return n<a?'Akan Datang':n>b?'Selesai':'LIVE'};onMounted(async()=>data.value=await api('/public/events-page'));</script><template><PublicPageShell><main v-if="data" class="page-main"><div class="container"><header class="text-center mb-5"><span class="section-eyebrow">{{data.page.eyebrow}}</span><h1 class="section-title">{{data.page.title}}</h1><p class="section-lead mx-auto">{{data.page.subtitle}}</p></header><div class="row g-4"><div v-for="event in data.events" :key="event.id" class="col-md-6 col-lg-4"><article class="program-card h-100"><img v-if="event.image_url" :src="event.image_url" class="w-100" :alt="event.title"><div class="program-card-body"><span :class="{'live-badge':status(event)==='LIVE'}">{{status(event)}}</span><h2 class="program-card-title">{{event.title}}</h2><p>{{event.description}}</p><router-link :to="`/event/${event.slug}`" class="btn btn-outline-danger rounded-pill">Detail Event</router-link></div></article></div></div></div></main></PublicPageShell></template><style scoped>.section-lead{color:#172033!important}.live-badge{display:inline-block;background:#16a34a;color:#fff;padding:.2rem .55rem;border-radius:999px;font-weight:800;font-size:.72rem;margin-bottom:.6rem}.live-badge::before{content:'● ';animation:pulse 1s infinite}@keyframes pulse{50%{opacity:.3}}</style>
